<?php
require_once __DIR__.'/../config/app.php';require_admin();
$stats=[
 'products'=>(int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn(),
 'customers'=>(int)db()->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),
 'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),
 'revenue'=>(float)db()->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE payment_status='paid'")->fetchColumn(),
 'pending'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE order_status='pending'")->fetchColumn(),
 'waiting'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE payment_status='waiting_verification'")->fetchColumn(),
 'low'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE stock<=minimum_stock AND stock>0')->fetchColumn(),
 'empty'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE stock=0')->fetchColumn(),
];
$recent=db()->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 8')->fetchAll();$low=db()->query('SELECT * FROM products WHERE stock<=minimum_stock ORDER BY stock ASC LIMIT 8')->fetchAll();
$chart=db()->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) orders,COALESCE(SUM(CASE WHEN payment_status='paid' THEN total_amount ELSE 0 END),0) revenue FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month")->fetchAll();$labels=array_column($chart,'month');$revenues=array_map('floatval',array_column($chart,'revenue'));$orderCounts=array_map('intval',array_column($chart,'orders'));
$pageTitle='Dashboard';$pageScript="const ctx=document.getElementById('salesChart');if(ctx)new Chart(ctx,{type:'bar',data:{labels:".json_encode($labels).",datasets:[{label:'Omzet',data:".json_encode($revenues).",backgroundColor:'#047857',borderRadius:8,yAxisID:'y'},{label:'Pesanan',data:".json_encode($orderCounts).",type:'line',borderColor:'#d4af37',backgroundColor:'#d4af37',tension:.35,yAxisID:'y1'}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true},y1:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false}}}}});";require APP_ROOT.'/includes/admin-header.php';
?>
<div class="row g-3 mb-4"><?php $cards=[['products','box-seam','Total Produk'],['customers','people','Total Pembeli'],['orders','bag-check','Total Pesanan'],['revenue','cash-stack','Omzet Lunas']];foreach($cards as [$key,$icon,$label]):?><div class="col-6 col-xl-3"><div class="stat-card"><div class="d-flex justify-content-between"><div><div class="text-muted small"><?= $label ?></div><div class="stat-value mt-1"><?= $key==='revenue'?rupiah($stats[$key]):number_format($stats[$key]) ?></div></div><span class="stat-icon"><i class="bi bi-<?= $icon ?>"></i></span></div></div></div><?php endforeach;?></div>
<div class="row g-3 mb-4"><?php $mini=[['pending','clock','Pesanan pending','warning'],['waiting','credit-card','Menunggu verifikasi','info'],['low','exclamation-triangle','Stok menipis','warning'],['empty','x-circle','Stok habis','danger']];foreach($mini as [$key,$icon,$label,$color]):?><div class="col-6 col-xl-3"><div class="admin-card p-3 d-flex gap-3 align-items-center"><span class="text-<?= $color ?> fs-3"><i class="bi bi-<?= $icon ?>"></i></span><div><strong class="fs-5"><?= $stats[$key] ?></strong><div class="text-muted small"><?= $label ?></div></div></div></div><?php endforeach;?></div>
<div class="row g-4 mb-4"><div class="col-xl-8"><div class="admin-card"><div class="admin-card-header"><strong>Performa 6 bulan terakhir</strong></div><div class="admin-card-body" style="height:350px"><canvas id="salesChart"></canvas></div></div></div><div class="col-xl-4"><div class="admin-card h-100"><div class="admin-card-header"><strong>Quick action</strong></div><div class="admin-card-body d-grid gap-2"><a class="btn btn-primary text-start" href="<?= url('admin/product-create.php') ?>"><i class="bi bi-plus-circle me-2"></i>Tambah Produk</a><a class="btn btn-light-green text-start" href="<?= url('admin/orders.php?status=pending') ?>"><i class="bi bi-bag-check me-2"></i>Proses Pesanan</a><a class="btn btn-light text-start" href="<?= url('admin/payments.php') ?>"><i class="bi bi-credit-card me-2"></i>Verifikasi Pembayaran</a><a class="btn btn-light text-start" href="<?= url('admin/reports.php') ?>"><i class="bi bi-bar-chart me-2"></i>Lihat Laporan</a></div></div></div></div>
<div class="row g-4"><div class="col-xl-8"><div class="admin-card"><div class="admin-card-header"><strong>Transaksi terbaru</strong><a href="<?= url('admin/orders.php') ?>">Lihat semua</a></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Pesanan</th><th>Pembeli</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $row):?><tr><td><a class="fw-semibold" href="<?= url('admin/order-detail.php?id='.$row['id']) ?>"><?= e($row['order_number']) ?></a><div class="small text-muted"><?= date('d/m/Y H:i',strtotime($row['created_at'])) ?></div></td><td><?= e($row['name']) ?></td><td><?= rupiah($row['total_amount']) ?></td><td><span class="badge text-bg-<?= status_class($row['order_status']) ?>"><?= order_status_label($row['order_status']) ?></span></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-xl-4"><div class="admin-card"><div class="admin-card-header"><strong>Stok perlu perhatian</strong></div><div class="admin-card-body"><?php if(!$low):?><p class="text-muted mb-0">Semua stok aman.</p><?php else:foreach($low as $product):?><div class="d-flex align-items-center justify-content-between py-2 border-bottom"><div><strong class="small"><?= e($product['name']) ?></strong><div class="text-muted" style="font-size:.72rem"><?= e($product['sku']) ?></div></div><span class="badge text-bg-<?= $product['stock']?'warning':'danger' ?>"><?= $product['stock'] ?></span></div><?php endforeach;endif;?></div></div></div></div>
